mapper.select:
SELECT COUNT(*)
FROM erp_payment_bill
WHERE student_id = #{studentId}
  AND yy = #{yy}
  AND mm = #{mm}
  AND bill_type = #{billType}
  AND status IN ('issued', 'approved', 'partial');

SELECT *
FROM erp_payment
WHERE student_id = #{studentId}
  AND yy = #{year}
  AND mm = #{month}

SELECT fee
FROM ERP_CLASS_FEE_MAP
WHERE class_key = #{classKey}
  AND center_code = #{centerCode}

SELECT TOP 1 payment_key
FROM erp_payment
WHERE student_id = #{studentId}
  AND yy = #{yy}
  AND mm = #{mm}
ORDER BY created_at DESC

SELECT s.student_id AS studentId, (p.yy + '-' + p.mm) AS classDate, s.student_name AS studentName, p.payment_key AS paymentKey,
STUFF(( SELECT ', ' + sub.class_name FROM ( SELECT DISTINCT cc2.class_name, cc2.class_type FROM erp_time_table_assign ta2 JOIN erp_time_table t2 ON ta2.time_table_key = t2.time_table_key JOIN erp_class_code cc2 ON cc2.class_key = CASE WHEN t2.class_key = 'COM' THEN ta2.class_key ELSE t2.class_key END WHERE ta2.student_id = p.student_id AND t2.yy = p.yy AND t2.mm = p.mm) AS sub ORDER BY sub.class_type FOR XML PATH (''), TYPE ).value('.', 'NVARCHAR(MAX)'), 1, 2, '') AS subject, hu.user_name AS hanTeacher, bu.user_name AS bookTeacher, p.amount AS amount, p.status, p.paid_date AS paidDate, ta.han_material_fee AS hanMaterialFee, ta.book_material_fee AS booKMaterialFee, edu.han_fee AS hanFee, edu.book_fee AS bookFee
FROM erp_payment p LEFT JOIN ( SELECT pd.payment_key, MAX(CASE WHEN class_type = '1' THEN pd.amount END ) AS han_fee, MAX(CASE WHEN class_type = '2' THEN pd.amount END ) AS book_fee FROM erp_payment_detail pd GROUP BY pd.payment_key) AS edu ON p.payment_key = edu.payment_key JOIN erp_student s ON p.student_id = s.student_id JOIN erp_teacher_assign ta ON s.student_id = ta.student_id LEFT JOIN erp_user hu ON ta.assign_han_teacher = hu.user_code LEFT JOIN erp_user bu ON ta.assign_book_teacher = bu.user_code WHERE s.center_code = #{centerCode}
AND p.student_id = #{studentId}
ORDER BY classDate DESC;

SELECT payment_key
FROM erp_payment
WHERE student_id = #{studentId}
  AND yy = #{year}
  AND mm = #{month}

SELECT p.payment_key
FROM erp_payment p
         JOIN erp_payment_detail pd ON p.payment_key = pd.payment_key
WHERE p.student_id = #{studentId}
  AND pd.time_table_key = #{timeTableKey}
GROUP BY p.payment_key

mapper.delete:
DELETE
FROM erp_payment_detail
WHERE time_table_key = #{timeTableKey}
  AND payment_key = #{paymentKey}
